'use strict';
// Presentation adapters keep itinerary, navigation and time calculations intact.
function visualWeek(d){return new Intl.DateTimeFormat('zh-CN',{weekday:'short',timeZone:'UTC'}).format(new Date(d.date+'T12:00:00Z')).replace('星期','周');}
const visualOriginalSummary=homeDaySummary;
homeDaySummary=function(d,label,isCurrent=false){const tpl=document.createElement('template');tpl.innerHTML=visualOriginalSummary(d,label,isCurrent);const card=tpl.content.firstElementChild,head=card.querySelector('header'),title=card.querySelector('h2'),route=card.querySelector('.home-summary-route'),list=card.querySelector('ul'),key=representative(d),src=key&&smallPhoto(key);head.querySelector('p').className='summary-badge';head.querySelector('p').textContent=label;head.querySelector('button').textContent='详情 ›';title.textContent=shortDate(d.date)+' · '+d.title;const body=document.createElement('div');body.className='home-summary-body'+(src?'':' no-photo');if(src){const img=document.createElement('img');img.className='home-summary-photo';img.src=src;img.width=720;img.height=480;img.alt=DATA.places[key].name;img.loading='lazy';img.decoding='async';body.append(img);}list.querySelectorAll('time').forEach(t=>{const full=t.textContent,m=full.match(/\d{1,2}:\d{2}/);if(m){t.setAttribute('aria-label',full);t.textContent=m[0];}});body.append(list);card.append(body);return card.outerHTML;};
home=function(){const t=tripToday(new Date(),DATA.days,tripCalendarChanges),before=t.boundary==='first',days=Math.max(0,Math.ceil((tripLocalTimestamp(DATA.days[0].date,'00:00','Asia/Shanghai')-Date.now())/86400000));return `<header class="visual-home-heading"><h1>Nordic Journal 2026</h1><p class="home-chinese-title">北欧路书</p><p class="home-subtitle">挪威 · 冰岛 · 18天 <span>10.18 — 11.04</span></p></header><figure class="home-cover-strip"><img src="${pImage('hamnoy')}" width="1176" height="805" alt="Hamnøy红屋与罗弗敦山海" fetchpriority="high" decoding="async"></figure><div class="home-date-entry visual-date-entry"><div class="home-date-strip" role="group" aria-label="选择行程日期">${DATA.days.map(d=>`<button data-home-date="${d.id}" aria-pressed="${d.id===t.day}"><time>${shortDate(d.date)}</time><small>${visualWeek(d)}</small></button>`).join('')}</div><div hidden>${journeyDate(t.day)}</div><button data-open-home-day aria-label="查看所选日期行程">查看日程 →</button></div><section class="journey-home-status"><header><span>${before?'距出发 '+days+' 天':t.inTrip?'今天与明天':'旅程回顾'}</span><button data-view="itinerary">全部日期 ›</button></header><div class="home-summaries">${homeSummaries(t)}</div></section>${routeOverview()}<footer class="journal-footer"><span>Nordic Journal 2026</span><div><button data-credits>照片来源</button><button data-offline>离线资料</button><button data-top>回到顶部 ↑</button></div></footer>`;};
function mountVisual(){const active=document.querySelector('.home-date-strip [aria-pressed=true]'),strip=active?.parentElement;if(active&&strip){strip.scrollLeft=Math.max(0,active.offsetLeft-strip.offsetLeft-(strip.clientWidth-active.clientWidth)/2);} }
const visualOriginalDayView=dayView;
dayView=function(){const tpl=document.createElement('template');tpl.innerHTML=visualOriginalDayView();const header=tpl.content.querySelector('.day-utility'),nav=tpl.content.querySelector('.day-top-controls');if(header&&nav)tpl.content.insertBefore(nav,header);return [...tpl.content.childNodes].map(n=>n.outerHTML||n.textContent).join('');};
const visualOriginalToolbox=toolboxView;
toolboxView=function(){const tpl=document.createElement('template');tpl.innerHTML=visualOriginalToolbox();const header=tpl.content.querySelector('.utility-header'),sub=document.createElement('p');sub.className='toolbox-subtitle';sub.textContent='旅途中随时取用的信息';header.append(sub);const icons={activities:'pin',flights:'plane',hotels:'bed',transport:'car',emergency:'phone',lists:'bag',offline:'bag',roads:'map'};tpl.content.querySelectorAll('[data-tool]').forEach(b=>{b.insertAdjacentHTML('afterbegin',outlineIco(icons[b.dataset.tool]||'pin'));});return [...tpl.content.childNodes].map(n=>n.outerHTML||n.textContent).join('');};
const visualOriginalBookingQuick=bookingQuick;
bookingQuick=function(b){const tpl=document.createElement('template');tpl.innerHTML=visualOriginalBookingQuick(b);const card=tpl.content.firstElementChild,src=smallPhoto(b.spot);if(src){card.insertAdjacentHTML('afterbegin',`<img class="tool-card-photo" src="${src}" width="160" height="120" alt="${esc(DATA.places[b.spot]?.name||b.name)}" loading="lazy" decoding="async">`);}return card.outerHTML;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-home-date]');if(b){const select=document.querySelector('.home-date-entry [data-journey-date]');if(select)select.value=b.dataset.homeDate;document.querySelectorAll('[data-home-date]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}const tab=e.target.closest('[data-map-panel]');if(tab){mapPanelTab=tab.dataset.mapPanel;visualMapPanel();}});
let mapPanelTab='places';
function visualMapPanel(){document.querySelectorAll('[data-map-panel]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.mapPanel===mapPanelTab)));const places=document.querySelector('#mapPlaces'),route=document.querySelector('#mapRouteActions');if(places)places.hidden=mapPanelTab!=='places';if(route)route.hidden=mapPanelTab!=='route';}
document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-map-panel]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=document.querySelector('[data-map-panel="'+((e.key==='Home'||e.key==='ArrowLeft')?'places':'route')+'"]');next.focus();next.click();});
const visualOriginalUpdateMap=updateMap;
updateMap=function(){visualOriginalUpdateMap();if(!map||mapFilter==='all')return;const seen=new Set();mapItems().forEach(item=>{const marker=mapMarkers.get(item.key),point=item.p.lat+':'+item.p.lon;if(marker&&!seen.has(point)){seen.add(point);marker.bindTooltip(esc(item.p.name),{permanent:true,direction:'top',offset:[0,-15],className:'route-place-label'});}});};
mapPage=function(){const today=mapBaseDay;return `<header class="utility-header visual-map-header"><h1>地图</h1><div class="segments map-mode" role="group" aria-label="地图日期"><button data-map-mode="current" data-mapday="${today}" aria-pressed="${mapFilter===String(today)}">当天</button><button data-map-mode="next" data-mapday="${Math.min(18,today+1)}" aria-pressed="${mapFilter===String(today+1)}" ${today===18?'disabled':''}>次日</button><button data-mapday="all" aria-pressed="${mapFilter==='all'}">全程</button></div><div class="utility-actions map-date-actions">${journeyDate(mapFilter==='all'?today:+mapFilter,true)}<button data-fit>适应路线</button><button data-map-return>${mapSource?.view==='day'?'返回当日行程':'返回行程'}</button></div><p id="mapIntro">${mapFilter==='all'?'全程地点与自驾道路':'当天主要地点与自驾道路'}</p></header><div class="atlas-workspace"><div class="map-wrap"><div id="routeMap" class="map" aria-label="互动旅程地图"><p class="map-loading">正在打开地图…</p></div></div><section class="map-bottom-panel" aria-label="路线与地点"><div class="map-panel-tabs" role="tablist" aria-label="地图资料"><button id="mapPlacesTab" data-map-panel="places" role="tab" aria-controls="mapPlaces" aria-selected="${mapPanelTab==='places'}">地点列表</button><button id="mapRouteTab" data-map-panel="route" role="tab" aria-controls="mapRouteActions" aria-selected="${mapPanelTab==='route'}">路线概览</button></div><div id="selectedMapPlace" class="map-selection" aria-live="polite"></div><div id="mapPlaces" class="map-place-list" role="tabpanel" aria-labelledby="mapPlacesTab"></div><div id="mapRouteActions" role="tabpanel" aria-labelledby="mapRouteTab"></div></section></div>`;};
const visualOriginalMapList=renderMapList;
renderMapList=function(){visualOriginalMapList();const items=mapItems();if(mapFilter==='all'){const stages=document.querySelector('#mapPlaces').innerHTML,route=document.querySelector('#mapRouteActions');route.innerHTML=stages+route.innerHTML;document.querySelector('#mapPlaces').innerHTML=items.map((x,i)=>`<article class="map-place-row" data-map-row="${esc(x.key)}"><button data-map-place="${esc(x.key)}"><span class="map-order">${i+1}</span><span><strong>${esc(x.p.name)}</strong><small>${esc(placeKind(x.key))}</small></span><span>›</span></button><div class="map-row-actions">${ext(mapNavLink(x),'导航到此处','small-link')}${journeyParking(x.key)}<button data-day="${x.day}">对应行程</button></div></article>`).join('');}document.querySelectorAll('[data-map-row]').forEach(row=>{const key=row.dataset.mapRow,src=smallPhoto(key.replace(/^hotel:/,''));if(src){const button=row.querySelector('[data-map-place]'),img=document.createElement('img');img.className='map-row-thumb';img.src=src;img.width=160;img.height=120;img.alt='';img.loading='lazy';img.decoding='async';button.append(img);}});visualMapPanel();};
function visualBookingDetail(b){const d=DATA.days[b.day-1],p=DATA.places[b.meeting||b.spot],src=pImage(b.spot),place=DATA.places[b.spot];return `<div class="visual-booking-detail">${src?`<div class="detail-photo"><img src="${src}" width="1200" height="800" alt="${esc(place?.name||b.name)}" loading="eager" fetchpriority="high" decoding="async"></div>`:''}<p class="detail-en">${dateText(d.date)} · ${esc(d.region)}</p><div class="booking-badges"><span>已订</span><span>${b.people}人参加</span></div><dl class="visual-booking-facts"><div><dt>报到目标</dt><dd>${esc(b.report)}</dd></div><div><dt>活动时间</dt><dd>${esc(b.time)}</dd></div><div><dt>集合位置</dt><dd>${esc(b.place)}</dd></div><div><dt>参与人数</dt><dd>${b.people}人</dd></div></dl><div class="booking-primary-actions">${ext(navLink(p),'导航到集合点','primary-link')}<button data-day="${b.day}" data-focus-step="${bookingRow(d,b)}">当日安排</button></div>${place?.desc?`<details class="journey-disclosure"><summary>活动简介</summary><div class="journey-detail-body"><p>${inline(place.desc)}</p></div></details>`:''}<details class="journey-disclosure"><summary>集合与凭证说明</summary><div class="journey-detail-body">${bookingNavigation(b)}</div></details><details class="journey-disclosure"><summary>注意事项</summary><div class="journey-detail-body"><p>${inline(b.note)}</p></div></details></div>`;}
